'use strict';
/* ---------- security helpers ---------- */
/* ids: only this exact shape is ever accepted from the DOM / from storage (same rule as App.js) */
const ID_RE=Object.freeze(/^[\w-]{1,40}$/);const okId=id=>typeof id==='string'&&ID_RE.test(id);
/* immutable constants: deepFreeze for data tables, fset for read-only "sets" (a native Set cannot be frozen) */
const deepFreeze=o=>{if(o&&typeof o==='object'&&!Object.isFrozen(o)){Object.freeze(o);Object.getOwnPropertyNames(o).forEach(k=>deepFreeze(o[k]))}return o};
const fset=a=>{const l=Object.freeze([...new Set(a)]);return Object.freeze({has:k=>l.includes(k),forEach:f=>l.forEach(x=>f(x,x))})};
